begin;
do $$
declare own uuid; guest uuid; g uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); pid uuid:=gen_random_uuid(); sid uuid; sid2 uuid; doc jsonb; before_payments jsonb; original_count int; ignored text; guest_email text;
begin
 select id into own from auth.users where not coalesce(is_anonymous,false) and email_confirmed_at is not null order by created_at limit 1;
 select id,email into guest,guest_email from auth.users where not coalesce(is_anonymous,false) and email_confirmed_at is not null and id<>own order by created_at limit 1;
 if guest is null then raise exception 'two confirmed fixture accounts required'; end if;
 perform set_config('request.jwt.claim.sub',own::text,true);
 insert into public.travel_groups(id,owner_id,name) values(g,own,'Temporary purchase test');
 insert into public.trips(id,group_id,organizer_id,name) values(t,g,own,'Temporary purchase test');
 insert into public.trip_access(trip_id,profile_id,role,granted_by) values(t,own,'organizer',own),(t,guest,'participant',own);
 insert into public.group_members(id,group_id,display_name,created_by) values(m,g,'Guest fixture',own);
 insert into public.trip_participants(id,trip_id,member_id,local_source_id) values(pid,t,m,'guest');
 insert into public.member_profile_links(member_id,profile_id,status,authorized_by) values(m,guest,'active',own);
 doc:=jsonb_build_object('trip',jsonb_build_object('id',t,'name','Test'),'shoppingYear',2026,'shoppingItems',jsonb_build_array(jsonb_build_object('id','item-test','year',2026,'trip',t,'name','Arroz','quantity',1,'unitPriceCents',1000,'actualTotalCents',1000,'purchased',false)),'payments',jsonb_build_array(jsonb_build_object('id','payment-test','amountCents',12345)),'expenses','[]'::jsonb);
 insert into public.trip_snapshots(trip_id,payload,revision,updated_by) values(t,doc,1,own);
 before_payments:=doc->'payments';
 perform set_config('request.jwt.claim.sub',guest::text,true);
 if not public.can_submit_trip_purchase(t) then raise exception 'guest cannot submit'; end if;
 if public.shopping_receipt_permission(t::text||'/'||own::text||'/photo.jpg',true) then raise exception 'wrong uploader accepted'; end if;
 begin perform public.submit_shopping_purchase(t,'item-test','Arroz',2,'kg',2100,current_date,'personal','','wrong/path.jpg'); raise exception 'invalid receipt accepted'; exception when others then if sqlerrm='invalid receipt accepted' then raise; end if; end;
 sid:=public.submit_shopping_purchase(t,'item-test','Arroz',2,'kg',2100,current_date,'personal','Compra teste',null);
 if (select status from public.shopping_purchase_submissions where id=sid)<>'submitted' then raise exception 'guest not pending'; end if;
 if (select s.payload->'shoppingItems'->0->>'purchased' from public.trip_snapshots s where trip_id=t)<>'false' then raise exception 'guest changed official item'; end if;
 begin perform public.submit_shopping_purchase(t,'item-test','Arroz',2,'kg',2100,current_date,'personal','',null); raise exception 'duplicate pending accepted'; exception when unique_violation then null; end;
 begin perform public.review_shopping_purchase(sid,true); raise exception 'guest approved purchase'; exception when others then if sqlerrm='guest approved purchase' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.review_shopping_purchase(sid,true);
 select s.payload into doc from public.trip_snapshots s where trip_id=t;
 if doc->'shoppingItems'->0->>'actualTotalCents'<>'2100' or doc->'shoppingItems'->0->>'purchased'<>'true' then raise exception 'official cost not updated'; end if;
 if doc->'payments'<>before_payments then raise exception 'payments changed'; end if;
 begin perform public.review_shopping_purchase(sid,true); raise exception 'repeat approval accepted'; exception when others then if sqlerrm='repeat approval accepted' then raise; end if; end;
 sid2:=public.submit_shopping_purchase(t,'item-test','Arroz',2,'kg',2100,current_date,'fund','Registro admin',null);
 if (select status from public.shopping_purchase_submissions where id=sid2)<>'confirmed' then raise exception 'admin not confirmed'; end if;
 if (select jsonb_array_length(s.payload->'shoppingItems') from public.trip_snapshots s where trip_id=t)<>1 then raise exception 'admin duplicate item'; end if;
 perform set_config('request.jwt.claim.sub',guest::text,true);
 if jsonb_array_length(public.get_shopping_purchase_workspace(t)->'submissions')<>1 then raise exception 'guest saw another persons records'; end if;
 sid2:=public.submit_shopping_purchase(t,null,'Gelo',1,'saco',1500,current_date,'personal','',null);
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.review_shopping_purchase(sid2,false);
 if (select jsonb_array_length(s.payload->'shoppingItems') from public.trip_snapshots s where trip_id=t)<>1 then raise exception 'rejection changed shopping'; end if;
 insert into public.trip_access(trip_id,profile_id,role,granted_by) values(t,guest,'organizer',own);
 ignored:=public.create_admin_invite(t,guest_email);
 perform set_config('request.jwt.claim.sub',guest::text,true);
 begin perform public.remove_event_administrator(t,own); raise exception 'guest removed owner'; exception when others then if sqlerrm='guest removed owner' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.remove_event_administrator(t,guest);
 if exists(select 1 from public.trip_access where trip_id=t and profile_id=guest and role='organizer') or not exists(select 1 from public.trip_access where trip_id=t and profile_id=guest and role='participant') then raise exception 'incorrect removal scope'; end if;
 if exists(select 1 from public.trip_invites where trip_id=t and role='organizer' and status='pending') then raise exception 'old admin invitation still usable'; end if;
 if has_column_privilege('authenticated','public.profiles','platform_owner','update') or not has_column_privilege('authenticated','public.profiles','display_name','update') then raise exception 'incorrect profile column grants'; end if;
 perform set_config('request.jwt.claim.sub','',true);
 if public.can_submit_trip_purchase(t) then raise exception 'unauthenticated purchase allowed'; end if;
end $$;
rollback;
select 'PASS: guest purchase pending, admin approval/rejection, costs updated once, payments preserved, own records only, private receipt ownership, administrator removal scope and platform flag protected; all fixture writes rolled back' as result;
